import React from 'react';
import { Icon as Iconify, addCollection } from '@iconify/react';
import icons from '../data/icons.json';

// Icons are bundled from src/data/icons.json (generated by scripts/prepare-icons.mjs),
// so rendering never reaches the Iconify API.
addCollection(icons);

export function Icon({ name, size = 18, ...props }) {
  return (
    <Iconify
      icon={`radar:${icons.icons[name] ? name : 'info'}`}
      width={size}
      height={size}
      aria-hidden="true"
      {...props}
    />
  );
}
